const fs = require("fs");
const path = require("path");
const { Queue } = require("./queue");
const { makeHttpJob } = require("./jobs/http");

const LOG_PATH = path.join(__dirname, "..", "errors.log");

async function main() {
  const q = new Queue({ concurrency: 4 });
  let errorCount = 0;

  // 每次运行先清掉旧日志，保证 JSON 行来自本次运行
  try {
    fs.unlinkSync(LOG_PATH);
  } catch {}

  // 不再吞错：计数 + 上报 + 写 errors.log
  q.on("error", (err, job) => {
    errorCount += 1;

    const record = {
      time: new Date().toISOString(),
      count: errorCount,
      id: job && job.id ? String(job.id) : "unknown",
      error: err && err.message ? err.message : String(err),
      stack: err && err.stack ? err.stack : undefined,
    };

    const line = JSON.stringify(record);

    try {
      fs.appendFileSync(LOG_PATH, line + "\n");
    } catch (e) {
      console.error("errors.log append failed", e);
    }

    console.error(`[error] ${line}`);
  });

  q.push(makeHttpJob({ id: "j1", url: process.env.J1_URL }));
  q.push(makeHttpJob({ id: "j2", url: process.env.J2_URL }));

  await q.drainUntilEmpty();
  console.log("ALL_DONE");
}

// 正常实现下不应触发；这里只用于兜底上报，不改变退出语义
process.on("unhandledRejection", (reason) => {
  console.error("unhandledRejection", reason);
});

main().catch((err) => {
  console.error("fatal", err);
  process.exit(1);
});
