const { EventEmitter } = require("events");

const microtask = (fn) => {
  if (typeof queueMicrotask === "function") return queueMicrotask(fn);
  return Promise.resolve().then(fn);
};

function getPriority(job) {
  const raw = job && (job.priority !== undefined ? job.priority : job.ctx && job.ctx.priority);

  if (typeof raw === "number" && Number.isFinite(raw)) return raw;

  if (typeof raw === "string") {
    const s = raw.trim().toLowerCase();
    if (s === "high") return 2;
    if (s === "low") return -2;
    if (s === "normal" || s === "medium") return 0;

    const n = Number(s);
    if (Number.isFinite(n)) return n;
  }

  return 0;
}

function toError(value) {
  if (value instanceof Error) return value;
  return new Error(value == null ? "unknown error" : String(value));
}

class Queue extends EventEmitter {
  constructor({ concurrency } = {}) {
    super();

    this.concurrency = Number.isInteger(concurrency) && concurrency > 0 ? concurrency : 1;

    this.items = [];
    this.running = 0;

    this._seq = 0;
    this._priorities = new Map();
    this._seqs = new Map();
    this._runningPriorities = new Map();
    this._settled = new WeakSet();

    this._draining = false;
    this._drainWaiter = null;
  }

  push(job) {
    if (typeof job === "object" && job !== null) {
      this._settled.delete(job);
    }

    const priority = getPriority(job);
    const seq = this._seq++;

    this._priorities.set(job, priority);
    this._seqs.set(job, seq);

    // 稳定优先级队列：高优先级在前；同优先级按注入顺序
    let i = 0;
    while (i < this.items.length) {
      const existing = this.items[i];
      const existingPriority = this._priorities.has(existing) ? this._priorities.get(existing) : 0;
      const existingSeq = this._seqs.has(existing) ? this._seqs.get(existing) : -1;

      if (existingPriority > priority || (existingPriority === priority && existingSeq < seq)) {
        i += 1;
      } else {
        break;
      }
    }

    this.items.splice(i, 0, job);

    if (this._draining) {
      this._pump();
    }
  }

  _topPriority() {
    let top = -Infinity;

    for (const p of this._runningPriorities.keys()) {
      if (p > top) top = p;
    }

    if (this.items.length > 0) {
      const first = this.items[0];
      const fp = this._priorities.has(first) ? this._priorities.get(first) : 0;
      if (fp > top) top = fp;
    }

    return Number.isFinite(top) ? top : null;
  }

  _pump() {
    const top = this._topPriority();
    if (top === null) return;

    // 关键：只启动当前最高优先级作业。
    // 这样同批注入的高优先级作业会先于低优先级完成。
    while (this.items.length > 0 && this.running < this.concurrency) {
      const first = this.items[0];
      const p = this._priorities.has(first) ? this._priorities.get(first) : 0;

      if (p !== top) break;

      const job = this.items.shift();
      this.running += 1;

      const count = this._runningPriorities.get(p) || 0;
      this._runningPriorities.set(p, count + 1);

      this._scheduleStart(job);
    }
  }

  _scheduleStart(job) {
    microtask(() => {
      try {
        let promise;

        try {
          promise = Promise.resolve(job.fn(job.ctx));
        } catch (err) {
          this._settle(job, err, undefined);
          return;
        }

        promise.then(
          (result) => this._settle(job, null, result),
          (err) => this._settle(job, err, undefined)
        );
      } catch (err) {
        try {
          this._settle(job, err, undefined);
        } catch {}
      }
    });
  }

  _settle(job, err, result) {
    if (typeof job === "object" && job !== null) {
      if (this._settled.has(job)) return;
      this._settled.add(job);
    }

    this.running -= 1;

    const p = this._priorities.has(job) ? this._priorities.get(job) : 0;

    if (this._runningPriorities.has(p)) {
      const next = this._runningPriorities.get(p) - 1;
      if (next <= 0) {
        this._runningPriorities.delete(p);
      } else {
        this._runningPriorities.set(p, next);
      }
    }

    this._priorities.delete(job);
    this._seqs.delete(job);

    try {
      if (err) {
        const error = toError(err);

        // 有监听者才 emit("error")，避免无监听时抛异常
        if (this.listenerCount("error") > 0) {
          this.emit("error", error, job);
        } else {
          console.error("[queue:error]", error.message);
        }
      } else {
        this.emit("done", job, result);
      }
    } catch (err) {
      console.error("[queue:listener-error]", err);
    }

    if (this.items.length > 0 || this.running > 0) {
      this._pump();
    }

    if (this._drainWaiter) {
      const resolve = this._drainWaiter;
      this._drainWaiter = null;
      microtask(() => resolve());
    }
  }

  async drainUntilEmpty() {
    this._draining = true;

    try {
      this._pump();

      while (this.items.length > 0 || this.running > 0) {
        if (this.running === 0) {
          this._pump();

          // 防御性分支：正常 concurrency >= 1 时不应发生
          if (this.running === 0 && this.items.length > 0) {
            await new Promise((resolve) => microtask(resolve));
            continue;
          }
        }

        if (this.items.length === 0 && this.running === 0) break;

        const waiter = new Promise((resolve) => {
          this._drainWaiter = resolve;
        });

        await waiter;
        this._pump();
      }
    } finally {
      this._draining = false;
      this._drainWaiter = null;
    }
  }
}

module.exports = { Queue };
