const http = require("http");

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function fetchOnce(url, timeoutMs) {
  return new Promise((resolve, reject) => {
    let settled = false;
    let req;

    const timer = setTimeout(() => {
      if (!settled) {
        settled = true;
        clearTimeout(timer);

        const err = new Error("timeout");
        reject(err);

        try {
          if (req) req.destroy(err);
        } catch {}
      }
    }, timeoutMs);

    const succeed = (value) => {
      if (!settled) {
        settled = true;
        clearTimeout(timer);
        resolve(value);
      }
    };

    const fail = (err) => {
      if (!settled) {
        settled = true;
        clearTimeout(timer);
        reject(err instanceof Error ? err : new Error(String(err)));
      }
    };

    try {
      req = http.get(url, { agent: false }, (res) => {
        res.on("error", (err) => fail(err));
        res.on("aborted", () => fail(new Error("aborted")));

        if (res.statusCode === 200) {
          // 完整消费响应后再结束，避免残留 socket
          res.resume();
          res.on("end", () => succeed("ok"));
        } else {
          const err = new Error("status " + res.statusCode);
          fail(err);

          try {
            res.destroy();
          } catch {}
        }
      });
    } catch (err) {
      fail(err);
      return;
    }

    req.on("error", (err) => fail(err));
    req.on("close", () => clearTimeout(timer));
  });
}

// 重试治理：async 循环 + 指数退避（100ms 起 ×2）
function makeHttpJob({ id, url, retries = 3 }) {
  return {
    id,
    ctx: { url },
    fn: async () => {
      let lastError;

      for (let attempt = 0; attempt <= retries; attempt++) {
        try {
          return await fetchOnce(url, 800);
        } catch (err) {
          lastError = err;

          if (attempt < retries) {
            const delay = 100 * Math.pow(2, attempt);
            await sleep(delay);
          }
        }
      }

      throw lastError instanceof Error ? lastError : new Error("http job failed");
    },
  };
}

module.exports = { makeHttpJob };
