package main

import (
	"context"
	"errors"
	"example.com/kvsrv/internal/api"
	"example.com/kvsrv/internal/server"
	"example.com/kvsrv/internal/store"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
)

func main() {
	st := store.New()
	mux := api.Routes(st)

	sigCh := make(chan os.Signal, 2)
	signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)
	firstCh := make(chan os.Signal, 1)
	go func() {
		first := false
		for sig := range sigCh {
			if !first {
				first = true
				select {
				case firstCh <- sig:
				default:
				}
				continue
			}
			log.Printf("second signal %v received; forcing exit", sig)
			os.Exit(1)
		}
	}()

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
	defer stop()

	srv := server.NewServer(":8080", mux)
	errCh := make(chan error, 1)
	go func() {
		errCh <- srv.ListenAndServe()
	}()

	select {
	case err := <-errCh:
		if errors.Is(err, http.ErrServerClosed) {
			return
		}
		log.Fatalf("server error: %v", err)
	case sig := <-firstCh:
		log.Printf("received signal %v; starting graceful shutdown", sig)
		gracefulShutdown(srv)
	case <-ctx.Done():
		log.Printf("received termination signal; starting graceful shutdown")
		gracefulShutdown(srv)
	}
}

func gracefulShutdown(srv *http.Server) {
	log.Printf("shutdown started; in-flight=%d", server.InFlight())

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := srv.Shutdown(ctx); err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			log.Printf("graceful shutdown timed out after 5s; forcing close")
		} else {
			log.Printf("graceful shutdown error: %v; forcing close", err)
		}
		_ = srv.Close()
	}
}
