package server

import (
	"fmt"
	"log"
	"net/http"
	"sync/atomic"
	"time"
)

const maxHeaderBytes = 1 << 20 // 1 MB

var inFlight int64

// InFlight returns the number of currently in-flight HTTP requests.
func InFlight() int64 { return atomic.LoadInt64(&inFlight) }

// NewServer creates an HTTP server with required timeouts and middleware.
func NewServer(addr string, h http.Handler) *http.Server {
	return &http.Server{
		Addr:           addr,
		Handler:        withRecover(withInFlight(h)),
		ReadTimeout:    5 * time.Second,
		WriteTimeout:   10 * time.Second,
		IdleTimeout:    120 * time.Second,
		MaxHeaderBytes: maxHeaderBytes,
	}
}

// ListenAndServe preserves the original entry-point signature.
func ListenAndServe(addr string, h http.Handler) error {
	return NewServer(addr, h).ListenAndServe()
}

func withInFlight(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt64(&inFlight, 1)
		defer atomic.AddInt64(&inFlight, -1)
		next.ServeHTTP(w, r)
	})
}

func withRecover(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rw := &recoverWriter{ResponseWriter: w}
		defer func() {
			if rec := recover(); rec != nil {
				log.Printf("panic recovered: %v", rec)
				if !rw.headerWritten {
					rw.Header().Set("Content-Type", "text/plain; charset=utf-8")
					rw.WriteHeader(http.StatusInternalServerError)
					_, _ = fmt.Fprint(rw, "internal server error\n")
				}
			}
		}()
		next.ServeHTTP(rw, r)
	})
}

type recoverWriter struct {
	http.ResponseWriter
	headerWritten bool
}

func (w *recoverWriter) WriteHeader(code int) {
	if !w.headerWritten {
		w.headerWritten = true
	}
	w.ResponseWriter.WriteHeader(code)
}

func (w *recoverWriter) Write(p []byte) (int, error) {
	if !w.headerWritten {
		w.WriteHeader(http.StatusOK)
	}
	return w.ResponseWriter.Write(p)
}
