package api

import (
	"encoding/json"
	"example.com/kvsrv/internal/store"
	"net/http"
	"time"
)

func Routes(st *store.Store) http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("/work", func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(200 * time.Millisecond) // simulate in-flight work
		key := r.URL.Query().Get("key")
		st.Set(key, "done")
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})

	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "alive"})
	})

	mux.HandleFunc("/readyz", func(w http.ResponseWriter, r *http.Request) {
		if st == nil {
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "unavailable"})
			return
		}

		const probeKey = "__readyz_probe__"
		st.Set(probeKey, "ok")
		v, ok := st.Get(probeKey)
		if !ok || v != "ok" {
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "unavailable"})
			return
		}

		writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
	})

	return mux
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}
```

原因/推理过程：

1. **优雅关闭与二次信号**
   - `main` 使用 `signal.NotifyContext(SIGTERM/SIGINT)` 获取取消上下文，满足任务要求。
   - 额外注册一个 `sigCh` 用于识别“第二次信号”：第一次只触发正常关闭，第二次直接 `os.Exit(1)` 强退。
   - 收到首次信号后调用 `srv.Shutdown(ctx)`，超时时间为 5s；若超时或失败，则调用 `srv.Close()` 强制关闭。

2. **服务器超时与 recover 中间件**
   - 新增 `server.NewServer` 用于创建带完整配置的 `*http.Server`：
     - `ReadTimeout=5s`
     - `WriteTimeout=10s`
     - `IdleTimeout=120s`
     - `MaxHeaderBytes=1MB`
   - `ListenAndServe` 签名保持不变，内部复用 `NewServer`，因此原有调用方式仍然可用。
   - `withRecover` 捕获 handler panic，未开始写响应时返回 500，避免进程崩溃。

3. **健康检查端点**
   - `/healthz`：存活检查，直接返回 200。
   - `/readyz`：通过固定保留键执行“写后读”探测；若 store 为 nil 或读写不一致，则返回 503。

4. **在途请求计数**
   - `withInFlight` 中间件使用原子计数器统计当前处理中的请求数。
   - 关闭开始时通过 `server.InFlight()` 打印日志，便于验证排空行为。

5. **约束满足**
   - `Routes`、`ListenAndServe`、`Store.Set`、`Store.Get` 签名均未改变。
   - 代码保持标准 Go 风格，`gofmt` 与 `go vet` 干净。
